package com.guardianxr.ar;
import android.app.*;import android.os.*;import android.graphics.Color;import android.content.*;import android.widget.*;
public class AdminActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);SharedPreferences p=getSharedPreferences("guardianxr",MODE_PRIVATE);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(30,50,30,30);l.setBackgroundColor(0xff07101c);TextView t=new TextView(this);t.setTextColor(Color.WHITE);t.setTextSize(19);t.setText("GuardianXR • OFFLINE COMPLIANCE DASHBOARD\n\nFire assessment: "+p.getInt("FIRE_score",0)+"%\nFire status: "+(p.getBoolean("FIRE_passed",false)?"PASSED":"PENDING")+"\n\nGas assessment: "+p.getInt("GAS_score",0)+"%\nGas status: "+(p.getBoolean("GAS_passed",false)?"PASSED":"PENDING")+"\n\nLast certificate: "+p.getString("last_cert","None")+"\n\nRecords are stored locally and remain available without internet.");l.addView(t);setContentView(l);}}
